"""Trusted QQ plugin HTTP adapter with durable, local effect fencing.

The plugin has neither effect-key idempotency nor receipt lookup. This ledger
prevents replay by this adapter; it does not confer either capability on QQ.
Only a proven pre-send rejection can be retried, explicitly, under the same key.
The host must supply trusted configuration and an owned persistent ledger path.
"""
from __future__ import annotations

import hashlib
import json
import re
import sqlite3
from contextlib import contextmanager
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Mapping
from urllib.parse import urlsplit

import httpx

from packages.jobs.actions import normalize_scheduled_qq_action


def _json(value: Any) -> str:
    return json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=False, allow_nan=False)


def _digest(value: Any) -> str:
    return hashlib.sha256(_json(value).encode()).hexdigest()


@dataclass(frozen=True)
class QQProviderConfig:
    endpoint: str
    bot_uins: tuple[str, ...]
    default_bot_uin: str

    def __post_init__(self):
        url = urlsplit(self.endpoint)
        if (url.scheme not in {"http", "https"} or not url.hostname or url.username
                or url.password or url.query or url.fragment or url.path not in {"", "/"}):
            raise ValueError("QQ endpoint must be a trusted HTTP origin")
        if (not self.bot_uins or len(set(self.bot_uins)) != len(self.bot_uins)
                or any(not isinstance(v, str) or not re.fullmatch(r"[1-9][0-9]{4,19}", v) for v in self.bot_uins)
                or self.default_bot_uin not in self.bot_uins):
            raise ValueError("QQ configuration requires unique explicit bot UINs and a configured default")

    @classmethod
    def from_host_config(cls, config: Mapping[str, Any], *, endpoint: str) -> QQProviderConfig:
        """Mirror bot.py selection precedence without importing/starting NoneBot.

        endpoint is the host's PAN_QQ_API_URL (or its explicit default), never a
        field from Job arguments. Missing bot identities fail closed.
        """
        qq = config.get("qq") or {}
        selected = qq.get("channel") or "napcat"
        sub = qq.get(selected) or {}
        if qq.get("plugin_id"):
            accounts = sub.get("accounts") if selected == "snowluma" else None
            rows = accounts if isinstance(accounts, list) and accounts else [sub]
        else:
            rows = [row for row in (qq.get("channels") or [])
                    if isinstance(row, dict) and str(row.get("name") or "").strip()]
            if not rows:
                rows = [sub]
        bots = tuple(str(row.get("bot_uin") or "") for row in rows)
        return cls(endpoint, bots, bots[0])


class QQChannelProvider:
    """One send per effect key, durable across provider/process recreation."""

    capabilities = {"remoteIdempotency": False, "remoteReceiptQuery": False,
                    "localReceiptQuery": True, "manualRetryProvenRejection": True}
    # These codes are emitted before bot.call_api in the existing plugin/channel.
    _NO_SEND = frozenset({"unknown_bot_uin", "bot_not_connected", "invalid_target_type",
                          "invalid_target_id", "empty_text"})

    def __init__(self, config: QQProviderConfig, ledger_path: Path, *, timeout: float = 5):
        self.config = config
        self.ledger_path = Path(ledger_path)
        self.timeout = timeout
        self.ledger_path.parent.mkdir(parents=True, exist_ok=True)
        with self._connect() as db:
            db.execute("CREATE TABLE IF NOT EXISTS qq_effects (key TEXT PRIMARY KEY, "
                       "binding TEXT NOT NULL, receipt TEXT NOT NULL, attempts INTEGER NOT NULL)")

    @contextmanager
    def _connect(self):
        db = sqlite3.connect(self.ledger_path, timeout=10)
        try:
            db.execute("PRAGMA synchronous=FULL")
            with db:
                yield db
        finally:
            db.close()

    @staticmethod
    def _key(effect_key: Mapping[str, Any]) -> str:
        key = dict(effect_key)
        if any(not isinstance(key.get(k), str) or not key[k] for k in ("runId", "stepId", "targetId")):
            raise ValueError("effectKey requires runId, stepId and targetId")
        n = key.get("operationOrdinal")
        if isinstance(n, bool) or not isinstance(n, int) or n < 0:
            raise ValueError("effectKey requires a nonnegative operationOrdinal")
        return _json(key)

    @staticmethod
    def _receipt(status: str, code: str, **fields) -> dict:
        return {"status": status, "code": code, "retryAllowed": status == "rejected", **fields}

    def query(self, effect_key: Mapping[str, Any]) -> dict:
        """Local evidence only. Unknown cannot be reconciled by the current plugin."""
        with self._connect() as db:
            row = db.execute("SELECT receipt FROM qq_effects WHERE key=?", (self._key(effect_key),)).fetchone()
        return json.loads(row[0]) if row else self._receipt("unknown", "no_local_receipt", remoteQuerySupported=False)

    async def send(self, target_type: str, target_id: str, text: str, *,
                   bot_uin: str | None = None, effect_key: Mapping[str, Any]) -> dict:
        return await self._send(target_type, target_id, text, bot_uin=bot_uin, effect_key=effect_key, retry=False)

    async def retry_rejected(self, target_type: str, target_id: str, text: str, *,
                             bot_uin: str | None = None, effect_key: Mapping[str, Any]) -> dict:
        """Host-authorized manual retry; no new effect identity or automatic retry."""
        return await self._send(target_type, target_id, text, bot_uin=bot_uin, effect_key=effect_key, retry=True)

    async def _send(self, target_type, target_id, text, *, bot_uin, effect_key, retry):
        key = self._key(effect_key)
        args = {"targetType": target_type, "targetId": target_id}
        if bot_uin is not None:
            args["botUin"] = bot_uin
        _, error = normalize_scheduled_qq_action({"api": "send_qq", "args": args})
        if error or not isinstance(text, str) or not text:
            raise ValueError(error or "QQ text must be a nonempty string")
        bot = bot_uin if bot_uin is not None else self.config.default_bot_uin
        if bot not in self.config.bot_uins:
            raise ValueError("Job botUin is not in trusted configuration")
        body = {"target_type": "private" if target_type == "user" else "group",
                "target_id": target_id, "text": text, "bot_uin": bot}
        binding = _digest({"endpoint": self.config.endpoint.rstrip("/"), "body": body})
        intent = self._receipt("unknown", "intent_persisted", remoteQuerySupported=False)
        with self._connect() as db:
            db.execute("BEGIN IMMEDIATE")
            row = db.execute("SELECT binding, receipt FROM qq_effects WHERE key=?", (key,)).fetchone()
            if row:
                if row[0] != binding:
                    raise ValueError("effectKey is already bound to a different QQ request or endpoint")
                receipt = json.loads(row[1])
                if not retry or receipt.get("status") != "rejected" or receipt.get("retryAllowed") is not True:
                    return receipt
                db.execute("UPDATE qq_effects SET receipt=?, attempts=attempts+1 WHERE key=?", (_json(intent), key))
            else:
                if retry:
                    raise ValueError("manual retry requires a persisted proven rejection")
                db.execute("INSERT INTO qq_effects VALUES (?, ?, ?, 1)", (key, binding, _json(intent)))
        # Transaction is committed before any network I/O. Crashes/cancellation
        # leave an unknown intent, including the unavoidable pre-send crash gap.
        result = intent
        try:
            async with httpx.AsyncClient(timeout=self.timeout, follow_redirects=False, trust_env=False) as client:
                response = await client.post(self.config.endpoint.rstrip("/") + "/api/qq/send", json=body)
            payload = response.json()
            if response.is_success and isinstance(payload, dict):
                err = payload.get("error")
                code = err.get("code") if isinstance(err, dict) else None
                if payload.get("ok") is False and isinstance(code, str) and code in self._NO_SEND:
                    result = self._receipt("rejected", code, noSendProven=True)
                elif (payload.get("ok") is True and not payload.get("error")
                      and isinstance(payload.get("message_id"), (str, int))
                      and not isinstance(payload["message_id"], bool)
                      and str(payload["message_id"]).strip()):
                    result = self._receipt("succeeded", "plugin_ack", messageId=str(payload["message_id"]))
                else:
                    result = self._receipt("unknown", "plugin_outcome_uncertain", remoteQuerySupported=False)
            else:
                result = self._receipt("unknown", "http_outcome_uncertain", remoteQuerySupported=False)
        except (httpx.HTTPError, ValueError):
            result = self._receipt("unknown", "transport_outcome_uncertain", remoteQuerySupported=False)
        with self._connect() as db:
            db.execute("UPDATE qq_effects SET receipt=? WHERE key=? AND binding=?", (_json(result), key, binding))
        return result
